content:
{
  "code": ".search-wrapper:focus-within {
  box-shadow: 0 0 0 2px var(--bg-pale-lavender), 0 0 0 4px var(--text-heading);
}

#search:disabled,
.clear-btn:disabled {
  opacity: 1;
  cursor: default;
  background: none;
}

.clear-btn[disabled] {
  display: flex;
}

.filter-chip:focus-visible {
  outline: 2px solid var(--text-heading);
  outline-offset: 2px;
}

.fav-btn:focus-visible,
.action-btn:focus-visible {
  outline: 2px solid var(--text-heading);
  outline-offset: 2px;
}

.fav-btn[disabled]:focus-visible {
  outline: none;
}

@media (max-width: 390px) {
  .mentor-card {
    padding: 14px;
  }

  .name {
    font-size: 15px;
  }

  .certification,
  .employer {
    font-size: 10px;
  }
}

@media (max-width: 320px) {
  .container {
    padding: 0 12px;
  }

  .header {
    padding-left: 12px;
  }

  .search-wrapper {
    height: 44px;
    padding: 0 10px;
  }

  .mentor-card {
    padding: 12px;
  }

  .name {
    font-size: 14px;
  }

  .description {
    -webkit-line-clamp: 3;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

[hidden] {
  display: none !important;
}"
}
